// Bundles the code editor page (Monaco + bridge, ADR-038) and the terminal page (xterm.js, ADR-071) into
// src/Vigo.App/Editor (generated: do not edit there).
// Usage: cd tools/editor && npm ci && node build.mjs
import { build } from 'esbuild';
import { cpSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, '../../src/Vigo.App/Editor');
const monaco = join(here, 'node_modules/monaco-editor');
const version = JSON.parse(readFileSync(join(monaco, 'package.json'), 'utf8')).version;

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });

const common = {
  bundle: true,
  minify: true,
  legalComments: 'none',
  target: 'chrome120',
  logLevel: 'warning',
  define: { 'process.env.NODE_ENV': '"production"' },
};

// Page: ES modules so that each language grammar is a chunk loaded on first use.
await build({
  ...common,
  entryPoints: { editor: join(here, 'src/editor.js') },
  outdir: out,
  format: 'esm',
  splitting: true,
  chunkNames: 'chunks/[name]-[hash]',
  loader: { '.ttf': 'file' },
  assetNames: '[name]',
});

// Generic editor worker (diff computation).
await build({
  ...common,
  entryPoints: { 'editor.worker': join(monaco, 'esm/vs/editor/editor.worker.js') },
  outdir: out,
  format: 'iife',
});

// Terminal page (xterm.js): one script and one stylesheet (xterm.css + terminal.css).
await build({
  ...common,
  entryPoints: { terminal: join(here, 'src/terminal.js') },
  outdir: out,
  format: 'iife',
  loader: { '.css': 'css' },
});

cpSync(join(here, 'src/index.html'), join(out, 'index.html'));
cpSync(join(here, 'src/terminal.html'), join(out, 'terminal.html'));
cpSync(join(here, 'src/boot.js'), join(out, 'boot.js'));
// UI messages of Monaco for the app languages other than English (multilingual app: FR + EN).
for (const lang of ['fr']) cpSync(join(monaco, `esm/vs/nls/lang/${lang}.js`), join(out, `nls.${lang}.js`));
cpSync(join(monaco, 'LICENSE'), join(out, 'LICENSE-monaco.txt'));
writeFileSync(join(out, 'README.txt'),
  `Generated by tools/editor/build.mjs from monaco-editor ${version} and xterm.js: do not edit, change tools/editor/src and rebuild.\n`);
console.log(`Editor and terminal bundled (monaco-editor ${version}, xterm.js) into ${out}`);
